 "content": "def transform(grid):
    """Shift the foreground pattern down one row, leaving background in place."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
